import unittest

from unique import stable_unique


class BehaviorTest(unittest.TestCase):
    def test_contract(self):
        for values, expected in [([], []), ([3, 1, 3, 2, 1], [3, 1, 2]), (["b", "a", "b"], ["b", "a"]), ([0, 2, 0], [0, 2])]:
